def experiment(inputs):
    import random
    params = inputs.get('parameters', {})
    feedback_intensity = params.get('feedback_intensity', 0.25)
    seeds = inputs.get('seeds', [13, 71, 43, 101, 202])
    spreads = []
    valid_flags = []
    for seed in seeds:
        random.seed(seed)
        val = random.random()
        for _ in range(50):
            val = (val + feedback_intensity * random.gauss(0, 1)) % 1.0
        spreads.append(abs(val - 0.5))
        valid_flags.append(True)
    avg_spread = sum(spreads) / len(spreads) if spreads else 0.0
    return {
        'measurements': {
            'distributional_spread': [avg_spread],
            'measurement_validity': [all(valid_flags)]
        }
    }

